sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cc-quick-actions {
    width: 100%;
    box-sizing: border-box;
    font-family: "Segoe UI", Arial, sans-serif;
   margin-left: 10%;
}

.cc-quick-header {
    margin-bottom: 12px;
}

.cc-quick-header h2 {
    margin: 0;
    font-size: 17px;
    font-weight: 700;
    color: #10233f;
}


/* Action Grid */
.cc-action-grid {
    display: grid;
    grid-template-columns: repeat(3, 1fr);
    gap: 10px;
    width: 100%;
}


/* Action Item */
.cc-action-item {
    height: 50px;
    box-sizing: border-box;

    display: flex;
    align-items: center;

    padding: 0 12px;

    background: #ffffff;
    border: 1px solid #cbd8e8;
    border-radius: 5px;

    cursor: pointer;

    /* Important because these are <a> links */
    color: #172b4d !important;
    text-decoration: none !important;

    transition: all 0.2s ease;
}


/* Prevent ServiceNow/browser default link styles */
.cc-action-item:link,
.cc-action-item:visited,
.cc-action-item:active {
    color: #172b4d !important;
    text-decoration: none !important;
}


/* Hover */
.cc-action-item:hover {
    border-color: #0879e8;
    background: #f7fbff;

    color: #172b4d !important;
    text-decoration: none !important;

    transform: translateY(-1px);
}


/* Icon */
.cc-action-icon {
    width: 30px;
    height: 30px;

    flex-shrink: 0;

    display: flex;
    align-items: center;
    justify-content: center;

    margin-right: 10px;

    background: #e7f1ff;
    border-radius: 5px;

    color: #0879e8;
    font-size: 17px;
    font-weight: 600;
}


/* Text */
.cc-action-item span {
    font-size: 13px;
    font-weight: 600;

    color: #172b4d !important;

    white-space: nowrap;
}


/* Responsive */
@media (max-width: 900px) {
    .cc-action-grid {
        grid-template-columns: repeat(2, 1fr);
    }
}

@media (max-width: 600px) {
    .cc-action-grid {
        grid-template-columns: 1fr;
    }

    .cc-action-item {
        height: 52px;
    }
}
